            const u = (await sql() `SELECT * FROM users WHERE email = ${normEmail(d.customer.email)}`)[0];
            if (u && u.sub_status === 'active')
                mail.paymentFailed(u.email, u.name, appUrl(req)).catch((e) => console.error(e));
