        const line = raw.trim();
        if (!line) {
            pending = '';
            continue;
        }
        if (/^(INT\.|EXT\.|INT\/EXT|I\/E\.|SCENE\b|CHAPTER\b)/i.test(line)) {
            setting = line.replace(/^SCENE\s*\d*\s*[:.-]?\s*/i, '').slice(0, 160);
            continue;
        }
        const bracket = line.match(/^[([](.*)[)\]]$/);
