            const sp = fitWords >= 4 ? (splitLine(l.text, fitWords) || (fitWords >= 6 && ws.length > fitWords + 2 ? [ws.slice(0, fitWords).join(' '), ws.slice(fitWords).join(' ')] : null)) : null;
